(()=>{'use strict';
const cfg=window.Essaint||{}, root=cfg.root||'/', $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
const money=c=>new Intl.NumberFormat(undefined,{style:'currency',currency:cfg.currency||'USD'}).format(c/100), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lastFocus,bag=[],toastTimer,searchTimer;try{bag=JSON.parse(localStorage.getItem('essaint-preview-bag')||'[]');if(!Array.isArray(bag))bag=[]}catch{};
function tell(msg){$('#status').textContent=msg;$('#status').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#status').classList.remove('visible'),5000)}
function openDialog(id){$$('dialog[open]').forEach(d=>d.close());lastFocus=document.activeElement;$(id).showModal()}
$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>lastFocus?.focus())});
async function request(path,body){const r=await fetch(root+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','Accept':'application/json'},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json()}catch{throw Error('The shop could not be reached. Please try again.')}if(!r.ok)throw Error(data.description||data.message||'Something went wrong. Please try again.');return data}
async function product(handle){if(cfg.preview){const p=window.EssaintCatalog.find(p=>p.handle===handle);if(!p)throw Error('This piece could not be found.');return p}return request('products/'+encodeURIComponent(handle)+'.js')}
const availableVariant=p=>p.variants.find(v=>v.available)||p.variants[0];
function variantOptions(p){return p.variants.map(v=>`<option value="${v.id}" ${!v.available?'disabled':''} ${v.id===availableVariant(p).id?'selected':''}>${esc(v.title)}${v.available?'':' — Sold out'} · ${money(v.price)}</option>`).join('')}
async function quick(handle){openDialog('#shop-dialog');$('#dialog-content').innerHTML='<p>Finding your next regular…</p>';try{const p=await product(handle);$('#dialog-content').innerHTML=`<div class="quick-product"><img src="${esc(p.featured_image)}" alt="${esc(p.title)}"><div><p class="eyebrow">THE ESSAINT WARDROBE</p><h2>${esc(p.title)}</h2><p class="price" id="quick-price">${money(availableVariant(p).price)}</p><form class="choice-form" id="quick-form"><label for="quick-variant">Choose your size / color</label><select id="quick-variant">${variantOptions(p)}</select><button class="button" ${p.variants.some(v=>v.available)?'':'disabled'}>Add to bag ↗</button></form><div class="rte quick-description">${p.description||''}</div><a class="text-link" href="${cfg.preview?'#product/'+p.handle:root+'products/'+p.handle}">View all details ↗</a></div></div>`;$('#quick-variant').onchange=e=>$('#quick-price').textContent=money(p.variants.find(v=>String(v.id)===e.target.value).price);$('#quick-form').onsubmit=e=>{e.preventDefault();addItems([{id:Number($('#quick-variant').value),quantity:1}],e.submitter)}}catch(e){$('#dialog-content').textContent=e.message}}
async function bundle(handles,title){openDialog('#shop-dialog');$('#dialog-content').innerHTML='<p>Putting your look together…</p>';try{const ps=await Promise.all(handles.split(',').map(product));$('#dialog-content').innerHTML=`<p class="eyebrow">BETTER TOGETHER / 2 PIECES</p><h2>${esc(title)}</h2><form id="bundle-form">${ps.map((p,i)=>`<div class="bundle-picker"><img src="${esc(p.featured_image)}" alt="${esc(p.title)}"><div><label for="bundle-${i}">${esc(p.title)}</label><select id="bundle-${i}" data-bundle-select>${variantOptions(p)}</select></div></div>`).join('')}<div class="bag-summary"><div><span>Your set</span><strong id="bundle-total"></strong></div><p>Choose each piece in your size. Any eligible discounts are applied at checkout.</p><button class="button" ${ps.every(p=>p.variants.some(v=>v.available))?'':'disabled'}>Add the set to bag ↗</button></div></form>`;const total=()=>$('#bundle-total').textContent=money(ps.reduce((s,p,i)=>s+p.variants.find(v=>String(v.id)===$('#bundle-'+i).value).price,0));total();$$('[data-bundle-select]').forEach(s=>s.onchange=total);$('#bundle-form').onsubmit=e=>{e.preventDefault();addItems(ps.map((p,i)=>({id:Number($('#bundle-'+i).value),quantity:1,properties:{'Outfit edit':title}})),e.submitter)}}catch(e){$('#dialog-content').textContent=e.message}}
async function addItems(items,button){if(button)button.disabled=true;try{if(cfg.preview){items.forEach(item=>{const p=window.EssaintCatalog.find(p=>p.variants.some(v=>v.id===item.id));const v=p?.variants.find(v=>v.id===item.id);if(!v?.available)throw Error('This size is sold out. Choose another option.');const existing=bag.find(b=>b.id===item.id);if(existing)existing.quantity+=item.quantity;else bag.push({...item,title:p.title,variant_title:v.title,price:v.price,image:p.featured_image})});saveBag()}else await request('cart/add.js',{items});$$('dialog[open]').forEach(d=>d.close());await showBag()}catch(e){tell(e.message)}finally{if(button)button.disabled=false}}
function saveBag(){try{localStorage.setItem('essaint-preview-bag',JSON.stringify(bag))}catch{}updateCount(bag.reduce((n,x)=>n+x.quantity,0))}
function updateCount(n){$$('[data-count]').forEach(e=>e.textContent=n)}
async function getCart(){if(cfg.preview){const offer=window.EssaintLinenOffer;const ids=new Set(window.EssaintCatalog.find(p=>p.handle===offer?.handle)?.variants.map(v=>v.id)||[]);const count=bag.filter(x=>ids.has(x.id)).reduce((n,x)=>n+x.quantity,0);const items=bag.map(x=>{const price=ids.has(x.id)?offer.unitPrice(count):x.price;return {...x,price,key:String(x.id),line_price:price*x.quantity,final_line_price:price*x.quantity,product_title:x.title,featured_image:{url:x.image}}});return {items,item_count:bag.reduce((n,x)=>n+x.quantity,0),total_price:items.reduce((n,x)=>n+x.final_line_price,0)}}return request('cart.js')}
async function showBag(){openDialog('#bag-dialog');$('#bag-content').innerHTML='<p>Opening your bag…</p>';await renderBag()}
async function renderBag(){try{const c=await getCart();updateCount(c.item_count);$('#bag-content').innerHTML=c.items.length?`${c.items.map(x=>`<div class="bag-item"><img src="${esc(x.featured_image?.url||x.image)}" alt="${esc(x.product_title)}"><div><strong>${esc(x.product_title)}</strong><p>${esc(x.variant_title||'')}</p><div class="quantity"><button data-change="${esc(x.key)}" data-quantity="${x.quantity-1}" aria-label="Decrease quantity of ${esc(x.product_title)}">−</button><span>${x.quantity}</span><button data-change="${esc(x.key)}" data-quantity="${x.quantity+1}" aria-label="Increase quantity of ${esc(x.product_title)}">+</button><button data-change="${esc(x.key)}" data-quantity="0" aria-label="Remove ${esc(x.product_title)}">×</button></div></div><span>${money(x.final_line_price)}</span></div>`).join('')}<div class="bag-summary"><div><span>Subtotal</span><strong>${money(c.total_price)}</strong></div><p>Shipping and taxes calculated at checkout.</p>${cfg.preview?'<p style="margin-top:15px">Preview bag only. Checkout is available after installing the theme on Shopify.</p><button class="button" disabled>Preview — checkout unavailable</button>':`<a class="button" href="${root}checkout">Checkout ↗</a><a class="text-link" href="${root}cart">View bag</a>`}</div>`:'<div class="empty-bag"><h3>Room for something good.</h3><p>Your bag is empty. Find your next everyday favorite.</p><button data-close class="button">Keep exploring ↗</button></div>'}catch(e){$('#bag-content').textContent=e.message}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.hasAttribute('data-menu')){const nav=$('.header nav'),isOpen=nav.classList.toggle('open');b.setAttribute('aria-expanded',isOpen)}if(b.hasAttribute('data-cart')){e.preventDefault();showBag()}if(b.hasAttribute('data-search')){openDialog('#search-dialog');$('#search-input').focus()}if(b.dataset.product){e.preventDefault();quick(b.dataset.product)}if(b.dataset.bundle){e.preventDefault();bundle(b.dataset.bundle,b.dataset.title)}if(b.dataset.change){b.disabled=true;try{if(cfg.preview){bag=bag.map(x=>String(x.id)===b.dataset.change?{...x,quantity:Number(b.dataset.quantity)}:x).filter(x=>x.quantity>0);saveBag()}else await request('cart/change.js',{id:b.dataset.change,quantity:Number(b.dataset.quantity)});await renderBag()}catch(err){tell(err.message);b.disabled=false}}});
$$('.native-product-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);addItems([{id:Number(d.get('id')),quantity:Number(d.get('quantity')||1)}],e.submitter)}));
$$('[data-variant-select]').forEach(s=>s.addEventListener('change',()=>{$('[data-product-price]').textContent=money(Number(s.selectedOptions[0].dataset.price))}));
$('#search-input')?.addEventListener('input',e=>{clearTimeout(searchTimer);const q=e.target.value.trim();if(q.length<2){$('#search-results').innerHTML='';return}searchTimer=setTimeout(async()=>{try{const results=cfg.preview?window.EssaintCatalog.filter(p=>p.title.toLowerCase().includes(q.toLowerCase())).slice(0,6):(await request('search/suggest.json?q='+encodeURIComponent(q)+'&resources[type]=product&resources[limit]=6')).resources.results.products;if($('#search-input').value.trim()!==q)return;$('#search-results').innerHTML=results.length?results.map(p=>`<button class="search-hit" data-product="${esc(p.handle)}"><img src="${esc(p.featured_image?.url||p.featured_image||p.image)}" alt=""><span>${esc(p.title)}</span></button>`).join(''):'<p>No pieces found. Try “striped” or “tee”.</p>'}catch(e){$('#search-results').textContent=e.message}},250)});
if(cfg.preview)saveBag();else getCart().then(c=>updateCount(c.item_count)).catch(()=>{});
window.EssaintUI={quick,bundle,money,esc,addItems,product};
})();
